/*
 * A167154  Numbers where terms in A167153 change parity: a(n)+1 is in
 *          A167153, but a(n)-1 is not.
 * https://oeis.org/A167154
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  more, nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 10, u32 n <= 10, u64 n <= 10, u128 n <= 10,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A167154:  Numbers where terms in A167153 change parity.
 *
 * The sequence is generated by the following recurrence:
 *   a(1) = 9
 *   for n > 1  :  a(n) = a(n-1) + d(n-1)
 *
 * where the increment d(k) depends only on k:
 *   d(k) = 21  if k == 1 or k == 3
 *   d(k) = 19  if k == 2 or k == 4
 *   d(k) = 111 if k == 5
 *   d(k) = 199 if k >= 6 and k is even
 *   d(k) = 201 if k >= 6 and k is odd
 *
 * This implements OEIS A167154 exactly. */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;                /* undefined for offset 1, but safe */

    seq_t value = (seq_t)9;            /* a(1) */
    if (n == 1)
        return value;

    /* Handle the first five differences explicitly */
    if (n >= 2) { value += (seq_t)21; } /* d(1) */
    if (n >= 3) { value += (seq_t)19; } /* d(2) */
    if (n >= 4) { value += (seq_t)21; } /* d(3) */
    if (n >= 5) { value += (seq_t)19; } /* d(4) */
    if (n >= 6) { value += (seq_t)111; }/* d(5) */

    /* For k >= 6 add the alternating 199/201 increments */
    for (idx_t k = 6; k < n; ++k) {
        value += (seq_t)((k & 1U) ? 201 : 199);
    }
    return value;
}
